    return bytes(x ^ y for x, y in zip(a, key_repeated))

def try_decode_hex(data):
    try:
        # Try to handle various hex formats
        if isinstance(data, bytes):
            hex_str = data.decode('utf-8')
        else:
            hex_str = str(data)

        # Remove common prefixes and clean up
        hex_str = hex_str.replace('\\x', '').replace('0x', '').replace(' ', '')
        return bytes.fromhex(hex_str)
    except:
        return data

def is_printable(s):
    return all(32 <= c <= 126 for c in s)

